export function decodeBinaryAscii(bits) {
  if(bits.length%7!==0||!/^[01]*$/.test(bits))throw new Error('Invalid bitstream');
  let out='';for(let i=0;i<bits.length;i+=7)out+=String.fromCharCode(parseInt(bits.slice(i,i+7),2));
  return out;
}
